/****** Object:  View [dbo].[v_FieldMap_WithFmt]    Script Date: 2026/9/13 下午 11:03:20 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create View [dbo].[v_FieldMap_WithFmt] as
SELECT  CancerRegistry_FmtField.序號, CancerRegistry_FmtField.中文欄位名稱, CancerRegistry_FieldMap.英文欄位名稱, 
        CancerRegistry_FieldMap.台大雲林欄位名稱, CancerRegistry_FieldMap.台大體系醫整庫欄位名稱, 
        CancerRegistry_FieldMap.台灣癌症登記中心, CancerRegistry_FieldMap.雲醫癌AI模組, CancerRegistry_FmtField.[42欄位], 
        CancerRegistry_FmtField.[45欄位], CancerRegistry_FmtField.[50欄位], CancerRegistry_FmtField.[114欄位], 
        CancerRegistry_FmtField.[115欄位], CancerRegistry_FmtField.[129欄位]
FROM    CancerRegistry_FieldMap LEFT OUTER JOIN CancerRegistry_FmtField ON CancerRegistry_FieldMap.序號 = CancerRegistry_FmtField.序號
GO
