INSERT [dbo].[CancerRegistry_FieldMap] ([編號], [序號], [中文欄位名稱], [英文欄位名稱], [台大雲林欄位名稱], [台大體系醫整庫欄位名稱], [台灣癌症登記中心], [雲醫癌AI模組], [define]) VALUES (16, N'2.7', N'側性', N'Laterality', N'側性', N'LAT95', N'lateral', N'lateral', N'0：非成對器官。
