ALTER TABLE [dbo].[LLMTaskWorker] CHECK CONSTRAINT [CK_LLMTaskWorker_Status]
GO
ALTER TABLE [dbo].[LLMTaskWorker]  WITH CHECK ADD  CONSTRAINT [CK_LLMTaskWorker_TaskType] CHECK  (([TaskType]=N'comparison_report' OR [TaskType]=N'annual_report' OR [TaskType]=N'compare' OR [TaskType]=N'chart'))
